/**
 * Run the seeded add system workflow when the local pack has already been
 * bootstrapped. First-time installs and damaged packs fall back to addPack so
 * the public command remains usable even before the durable workflow exists.
 */
declare function runDurableAdd({ spec, global, yes }?: {
    global?: boolean | undefined;
    yes?: boolean | undefined;
}): Promise<{
    readonly runId: string;
    readonly status: "running" | "waiting-approval" | "waiting-event" | "waiting-timer" | "waiting-quota" | "paused" | "finished" | "continued" | "failed" | "cancelled";
    readonly output?: unknown;
    readonly error?: unknown;
    readonly nextRunId?: string;
    readonly failedChildren?: number;
    readonly failedChildKeys?: readonly string[];
    readonly exhaustedLoops?: readonly {
        readonly id: string;
        readonly iteration: number;
        readonly maxIterations: number | null;
    }[];
} | null>;

export { runDurableAdd };
